def vowel_consonant_count(s):
    vowels = set('aeiouAEIOU')
    v = 0
    c = 0
    for ch in s:
        if ch.isalpha():
            if ch.lower() in 'aeiou':
                v += 1
            else:
                c += 1
    return {'vowels': v, 'consonants': c}

def rotate_dict_values(d, n):
    keys = sorted(d.keys())
    m = len(keys)
    if m == 0:
        return {}
    values = [d[k] for k in keys]
    n = n % m
    rotated = values[-n:] + values[:-n]
    return dict(zip(keys, rotated))

def prefix_sum_by_sorted_key(d):
    result = {}
    total = 0
    for k in sorted(d.keys()):
        total += d[k]
        result[k] = total
    return result

def partition_by_sign(d):
    pos = {}
    nonpos = {}
    for k, v in d.items():
        if v > 0:
            pos[k] = v
        else:
            nonpos[k] = v
    return (pos, nonpos)

def zip_to_dict_first_wins(keys, values):
