def transpose_list_of_dicts(records):
    if not records:
        return {}
    keys = records[0].keys()
    return {k: [r[k] for r in records] for k in keys}

def multidict_from_pairs(pairs):
    result = {}
    for k, v in pairs:
        result.setdefault(k, []).append(v)
    return result

def sum_positive_by_key(pairs):
    result = {}
    for k, v in pairs:
        if v > 0:
            result[k] = result.get(k, 0) + v
    return result

def average_by_key_from_pairs(pairs):
    sums = {}
    counts = {}
    for k, v in pairs:
        sums[k] = sums.get(k, 0) + v
        counts[k] = counts.get(k, 0) + 1
    return {k: round(sums[k] / counts[k], 2) for k in sums}

def min_max_across_dicts(records):
    result = {}
    for d in records:
        for k, v in d.items():
            if k not in result:
                result[k] = [v, v]
            else:
                if v < result[k][0]:
                    result[k][0] = v
                if v > result[k][1]:
                    result[k][1] = v
    return {k: tuple(v) for k, v in result.items()}

def average_across_dicts_zero_fill(dicts_list):
    if not dicts_list:
        return {}
    n = len(dicts_list)
    keys = set()
    for d in dicts_list:
        keys.update(d.keys())
    result = {}
    for k in keys:
        total = sum(d.get(k, 0) for d in dicts_list)
        result[k] = round(total / n, 2)
    return result

def keys_present_in_exactly_two(dicts_list):
    counts = {}
    for d in dicts_list:
        for k in d:
            counts[k] = counts.get(k, 0) + 1
    return sorted(k for k, c in counts.items() if c == 2)

def merge_override(base, overrides):
    result = dict(base)
    for k, v in overrides.items():
        if k in base:
            result[k] = v
    return result

def aggregate_collect(records):
    result = {}
    for d in records:
        for k, v in d.items():
            result.setdefault(k, []).append(v)
    return result

def first_occurrence_indices(seq):
    result = {}
    for i, x in enumerate(seq):
        if x not in result:
            result[x] = i
    return result
